ies.append({ "ie_type" : "F-TEID", "ie_value" : "SGW S11/S4 IP Address and TEID for Control Plane", "presence" : "C", "instance" : "1", "comment" : "This IE shall be included if a SGW is being used by the old MME/SGSN, except if:the source and target MME/S4-SGSN support the MME/S4-SGSN triggered SGW restoration procedure, and the source MME/S4-SGSN has not performed the SGW relocation procedure after the source SGW has failed as specified in TS23.007[17].across the S16 interface if there is no active PDP contextacross the S10/N26 interface if the UE does not have any PDN connection through the SGW and PGW.This IE shall not be included by an old AMF."})
