ies.append({ "ie_type" : "RAT Type", "ie_value" : "RAT Type", "presence" : "CO", "instance" : "0", "comment" : "This IE shall be included by the source MME, SGSN or AMF on the S10, S16, S3 and N26 interface to indicate the old RAT type where the UE was camping. See NOTE 7."})
ies.append({ "ie_type" : "Serving PLMN Rate Control", "ie_value" : "Serving PLMN Rate Control", "presence" : "CO", "instance" : "0", "comment" : "This IE shall be included by the old MME on the S10 interface if such Serving PLMN Rate control was enabled when there is at least one SGi or SCEF PDN connection with the Control Plane Only Indication set. See NOTE 8. "})
